// src/components/SignUp.js
import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { toast } from 'react-toastify';

const SignUp = ({ onAuth }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
  });
  const [passwordStrength, setPasswordStrength] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    if (name === 'password') {
      if (value.length < 6) setPasswordStrength('Weak');
      else if (value.length < 10) setPasswordStrength('Moderate');
      else setPasswordStrength('Strong');
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const { firstName, lastName, email, password } = formData;

    if (firstName && lastName && email && password) {
      onAuth({ name: `${firstName} ${lastName}`, email });
      toast.success('Account created successfully!');
      navigate('/dashboard');
    } else {
      toast.error('Please fill out all fields');
    }
  };

  const handleClose = () => navigate('/');

  return (
    <div className="d-flex justify-content-center align-items-start min-vh-100 pt-5" style={{ backgroundColor: '#fffaf2' }}>
      <div className="card p-4 shadow-lg" style={{ width: '100%', maxWidth: '400px', borderRadius: '1rem' }}>
        <button onClick={handleClose} className="btn-close position-absolute end-0 m-3" aria-label="Close"></button>

        <h2 className="text-center mb-4 text-primary">Create Account</h2>

        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label">First Name</label>
            <input
              type="text"
              name="firstName"
              className="form-control"
              value={formData.firstName}
              onChange={handleChange}
              placeholder="John"
              required
            />
          </div>

          <div className="mb-3">
            <label className="form-label">Last Name</label>
            <input
              type="text"
              name="lastName"
              className="form-control"
              value={formData.lastName}
              onChange={handleChange}
              placeholder="Doe"
              required
            />
          </div>

          <div className="mb-3">
            <label className="form-label">Email</label>
            <input
              type="email"
              name="email"
              className="form-control"
              value={formData.email}
              onChange={handleChange}
              placeholder="you@example.com"
              required
            />
          </div>

          <div className="mb-2">
            <label className="form-label">Password</label>
            <input
              type="password"
              name="password"
              className="form-control"
              value={formData.password}
              onChange={handleChange}
              placeholder="••••••••"
              required
            />
          </div>

          {formData.password && (
            <div className="mb-3">
              <small className={`text-${passwordStrength === 'Weak' ? 'danger' : passwordStrength === 'Moderate' ? 'warning' : 'success'}`}>
                Password Strength: {passwordStrength}
              </small>
            </div>
          )}

          <button type="submit" className="btn btn-success w-100">Sign Up</button>
        </form>

        <p className="text-center mt-3 text-muted">
          Already have an account? <Link to="/signin" className="text-decoration-none text-primary">Sign In</Link>
        </p>
      </div>
    </div>
  );
};

export default SignUp;
